script:
// Publications, part 1: what the three pages share (P). Load order: pub_core,
// then the page's own script. Needs ui.js.
;(function () {
	'use strict'

	var MNA = (window.MNA = window.MNA || {})
	var P = (MNA.pub = {})
	var WORDS_PER_MINUTE = 200

	P.ICONS = {"arrow-left": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"m12 19-7-7 7-7\" />\n  <path d=\"M19 12H5\" /></svg>", "arrow-right": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M5 12h14\" />\n  <path d=\"m12 5 7 7-7 7\" /></svg>", "check": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M20 6 9 17l-5-5\" /></svg>", "globe": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><circle cx=\"12\" cy=\"12\" r=\"10\" />\n  <path d=\"M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20\" />\n  <path d=\"M2 12h20\" /></svg>", "pencil": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M21.174 6.812a1 1 0 0 0-3.986-3.987L3.842 16.174a2 2 0 0 0-.5.83l-1.321 4.352a.5.5 0 0 0 .623.622l4.353-1.32a2 2 0 0 0 .83-.497z\" />\n  <path d=\"m15 5 4 4\" /></svg>", "search": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><circle cx=\"11\" cy=\"11\" r=\"8\" />\n  <path d=\"m21 21-4.3-4.3\" /></svg>", "share-2": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><circle cx=\"18\" cy=\"5\" r=\"3\" />\n  <circle cx=\"6\" cy=\"12\" r=\"3\" />\n  <circle cx=\"18\" cy=\"19\" r=\"3\" />\n  <line x1=\"8.59\" x2=\"15.42\" y1=\"13.51\" y2=\"17.49\" />\n  <line x1=\"15.41\" x2=\"8.59\" y1=\"6.51\" y2=\"10.49\" /></svg>", "shield": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z\" /></svg>", "user": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2\" />\n  <circle cx=\"12\" cy=\"7\" r=\"4\" /></svg>", "user-minus": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\" />\n  <circle cx=\"9\" cy=\"7\" r=\"4\" />\n  <line x1=\"22\" x2=\"16\" y1=\"11\" y2=\"11\" /></svg>", "user-plus": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\" />\n  <circle cx=\"9\" cy=\"7\" r=\"4\" />\n  <line x1=\"19\" x2=\"19\" y1=\"8\" y2=\"14\" />\n  <line x1=\"22\" x2=\"16\" y1=\"11\" y2=\"11\" /></svg>", "x": "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"display:block;flex-shrink:0;width:16px;height:16px\"><path d=\"M18 6 6 18\" />\n  <path d=\"m6 6 12 12\" /></svg>"}
	P.API = 'cafe.api.'

	P.el = function (tag, className, text) {
		return MNA.el(tag, className, text)
	}

	P.icon = function (name, className) {
		var span = document.createElement('span')
		span.className = 'mna-p-icon ' + (className || '')
		span.innerHTML = (P.ICONS && P.ICONS[name]) || ''
		return span
	}

	P.svg = function (name) {
		return (P.ICONS && P.ICONS[name]) || ''
	}

	P.get = function (method, params) {
		return MNA.get(P.API + method, params)
	}
	P.call = function (method, args) {
		return MNA.api(P.API + method, args)
	}

	P.me = (function () {
		var match = document.cookie.match(/(?:^|;\s*)user_id=([^;]*)/)
		return match ? decodeURIComponent(match[1]) : ''
	})()

	// The handle: from /publications/<handle>[/members], or the page's own attribute (Builder's Preview).
	P.handle = function (root) {
		var match = location.pathname.match(/^\/publications\/([^/]+)/)
		return match ? decodeURIComponent(match[1]) : root.getAttribute('data-handle') || ''
	}

	P.avatar = function (image, label, size) {
		var box = P.el('span', 'mna-p-avatar mna-p-avatar-' + (size || 'md'))
		if (/^(\/|https?:\/\/)/.test(image || '')) {
			var img = P.el('img')
			img.src = image
			img.alt = ''
			box.appendChild(img)
		} else {
			box.textContent = String(label || '?')
				.trim()
				.charAt(0)
		}
		return box
	}

	// A small pill: kind is 'solid-green', 'blue' or 'gray'.
	P.badge = function (label, kind) {
		return P.el('span', 'mna-p-badge ' + (kind || 'gray'), label)
	}

	P.plainText = function (html) {
		return (new DOMParser().parseFromString(html || '', 'text/html').body.textContent || '').trim()
	}
	P.excerpt = function (html, length) {
		var text = P.plainText(html)
		return text.length > length ? text.slice(0, length) + '…' : text
	}
	P.readTime = function (html) {
		var words = P.plainText(html).split(/\s+/).filter(Boolean).length
		return Math.max(1, Math.round(words / WORDS_PER_MINUTE))
	}
	P.date = function (value) {
		if (!value) return ''
		return new Date(value.replace(' ', 'T')).toLocaleDateString(undefined, {
			month: 'short',
			day: 'numeric',
			year: 'numeric',
		})
	}

	P.errorToast = function (error) {
		MNA.toast((error && error.message) || MNA.DEFAULT_ERROR, 'error')
	}

	// Names on the page, whichever page it is.
	P.setTitle = function (title, alsoMobile) {
		var crumb = document.getElementById('mna-p-crumb')
		if (crumb) crumb.textContent = title
		var mobile = document.querySelector('.mna-mobile-title')
		if (alsoMobile && mobile) mobile.textContent = title
	}

	P.skeleton = function (lines) {
		var wrap = P.el('div', 'mna-p-skeleton')
		for (var i = 0; i < lines; i++) wrap.appendChild(P.el('div', 'mna-skeleton'))
		return wrap
	}
})()
